    private static int assertions;
    private static readonly BindingFlags Private = BindingFlags.Instance | BindingFlags.NonPublic;
    private static void Check(bool value,string message){assertions++;if(!value)throw new Exception(message);}
    private static void Call(object obj,string method,params object[] args){try{obj.GetType().GetMethod(method,Private).Invoke(obj,args);}catch(TargetInvocationException e){throw e.InnerException;}}
    private static T Field<T>(object obj,string field)=>(T)obj.GetType().GetField(field,Private).GetValue(obj);
    private static void Set(object obj,string field,object value)=>obj.GetType().GetField(field,Private).SetValue(obj,value);
    private static void Property(object obj,string name,object value)=>Set(obj,"<"+name+">k__BackingField",value);
    private static Vector3 V(JsonElement a)=>new Vector3(a[0].GetSingle(),a[1].GetSingle(),a[2].GetSingle());
    private static Vector3 Lerp(Vector3 a,Vector3 b,float t)=>a+(b-a)*t;
    private static float[] A(Vector3 v)=>new[]{v.x,v.y,v.z};
    private static float[] A(Quaternion q)=>new[]{q.x,q.y,q.z,q.w};
    private struct Pose {public Vector3 position,scale;public Quaternion rotation;}
    private sealed class Frame {public Pose[] bones;public Dictionary<int,Vector3>[] cloud;public float[] meshMinimum;}
    private sealed class Fixture
    {
        public string sourceHash;public float scale;public string[] names;public int[] parents;public Frame idle;public Dictionary<string,Frame[]> clips=new Dictionary<string,Frame[]>();public JsonElement calibration;
        public Fixture(string path){using(var doc=JsonDocument.Parse(File.ReadAllText(path))){var d=doc.RootElement;sourceHash=d.GetProperty("sourceSha256Before").GetString();scale=d.GetProperty("worldScale").GetSingle();names=d.GetProperty("bones").EnumerateArray().Select(x=>x.GetString()).ToArray();parents=d.GetProperty("parents").EnumerateArray().Select(x=>x.GetInt32()).ToArray();calibration=d.GetProperty("calibration").Clone();idle=Read(d.GetProperty("idle"));foreach(var c in d.GetProperty("clips").EnumerateObject())clips[c.Name]=c.Value.GetProperty("samples").EnumerateArray().Select(Read).ToArray();}}
        private Vector3 World(JsonElement p)=>new Vector3(p[0].GetSingle(),p[2].GetSingle(),-p[1].GetSingle())*scale;
        private Frame Read(JsonElement row){var result=new Frame{bones=new Pose[names.Length],cloud=new[]{new Dictionary<int,Vector3>(),new Dictionary<int,Vector3>()},meshMinimum=new float[2]};var world=new N.Matrix4x4[names.Length];var qConvert=Quaternion.AngleAxis(-90,new Vector3(1,0,0));
            for(int i=0;i<names.Length;i++){var a=row[1][i];var p=new Vector3(a[0].GetSingle(),a[2].GetSingle(),-a[1].GetSingle())*scale;var q=qConvert*new Quaternion{w=a[3].GetSingle(),x=a[4].GetSingle(),y=a[5].GetSingle(),z=a[6].GetSingle()};var s=new Vector3(a[7].GetSingle(),a[8].GetSingle(),a[9].GetSingle());world[i]=N.Matrix4x4.CreateScale(s.n)*N.Matrix4x4.CreateFromQuaternion(q.n)*N.Matrix4x4.CreateTranslation(p.n);var local=world[i];if(parents[i]>=0){N.Matrix4x4.Invert(world[parents[i]],out var inverse);local*=inverse;}Check(N.Matrix4x4.Decompose(local,out var ls,out var lq,out var lp),"source local TRS decomposes");result.bones[i]=new Pose{position=Vector3.V(lp),rotation=Quaternion.Q(lq),scale=Vector3.V(ls)};}
            for(int side=0;side<2;side++){var foot=row[2][side];result.meshMinimum[side]=foot[0].GetSingle()*scale;N.Matrix4x4.Invert(world[4+side],out var inverse);foreach(var point in foot[4].EnumerateArray()){var p=new Vector3(point[1].GetSingle(),point[3].GetSingle(),-point[2].GetSingle())*scale;result.cloud[side][point[0].GetInt32()]=Vector3.V(N.Vector3.Transform(p.n,inverse));}}
            return result;}
        public Frame At(string name,float phase){if(name.Contains("+")){var pair=name.Split('+');return Blend(At(pair[0],phase),At(pair[1],phase),4f/7f);}var frames=clips[name];float value=(phase-(float)Math.Floor(phase))*(frames.Length-1);int first=(int)value;int last=Math.Min(first+1,frames.Length-1);float t=value-first;var a=frames[first];var b=frames[last];var result=new Frame{bones=new Pose[names.Length],cloud=new[]{new Dictionary<int,Vector3>(),new Dictionary<int,Vector3>()},meshMinimum=new float[2]};
            for(int i=0;i<names.Length;i++)result.bones[i]=new Pose{position=Lerp(a.bones[i].position,b.bones[i].position,t),rotation=Quaternion.Slerp(a.bones[i].rotation,b.bones[i].rotation,t),scale=Lerp(a.bones[i].scale,b.bones[i].scale,t)};
            for(int side=0;side<2;side++){result.meshMinimum[side]=a.meshMinimum[side]+(b.meshMinimum[side]-a.meshMinimum[side])*t;foreach(var kv in a.cloud[side])result.cloud[side][kv.Key]=b.cloud[side].TryGetValue(kv.Key,out var p)?Lerp(kv.Value,p,t):kv.Value;foreach(var kv in b.cloud[side])if(!result.cloud[side].ContainsKey(kv.Key))result.cloud[side][kv.Key]=kv.Value;}
            return result;}
        private Frame Blend(Frame a,Frame b,float t){var result=new Frame{bones=new Pose[names.Length],cloud=new[]{new Dictionary<int,Vector3>(),new Dictionary<int,Vector3>()},meshMinimum=new float[2]};for(int i=0;i<names.Length;i++)result.bones[i]=new Pose{position=Lerp(a.bones[i].position,b.bones[i].position,t),rotation=Quaternion.Slerp(a.bones[i].rotation,b.bones[i].rotation,t),scale=Lerp(a.bones[i].scale,b.bones[i].scale,t)};for(int side=0;side<2;side++){result.meshMinimum[side]=a.meshMinimum[side]+(b.meshMinimum[side]-a.meshMinimum[side])*t;foreach(var kv in a.cloud[side])result.cloud[side][kv.Key]=b.cloud[side].TryGetValue(kv.Key,out var q)?Lerp(kv.Value,q,t):kv.Value;foreach(var kv in b.cloud[side])if(!result.cloud[side].ContainsKey(kv.Key))result.cloud[side][kv.Key]=kv.Value;}return result;}
    }
    private struct TruthPoint {public Vector3 footLocal,toeLocal;public float weight;}
    private sealed class ProfileData
    {
        public TruthPoint[][] truth=new TruthPoint[2][];
        public IntercomGroundFeedbackSoleProfile asset=new IntercomGroundFeedbackSoleProfile();public Dictionary<int,float>[] weights={new Dictionary<int,float>(),new Dictionary<int,float>()};
        public ProfileData(string path,float scale){using(var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(Path.GetDirectoryName(path),Path.GetFileNameWithoutExtension(path)+".truth.json")))){for(int side=0;side<2;side++)truth[side]=doc.RootElement.GetProperty("points").GetProperty(side==0?"L":"R").EnumerateArray().Select(a=>new TruthPoint{footLocal=new Vector3(a[1].GetSingle(),a[2].GetSingle(),a[3].GetSingle())*scale,toeLocal=new Vector3(a[4].GetSingle(),a[5].GetSingle(),a[6].GetSingle())*scale,weight=a[7].GetSingle()}).ToArray();}using(var doc=JsonDocument.Parse(File.ReadAllText(path))){var d=doc.RootElement;foreach(var side in new[]{"L","R"}){var points=d.GetProperty("points").GetProperty(side);var ids=d.GetProperty("vertexIndices").GetProperty(side);int index=side=="L"?0:1;var data=new IntercomGroundFeedbackSoleProfile.Point[points.GetArrayLength()];for(int i=0;i<data.Length;i++){var p=points[i];data[i]=new IntercomGroundFeedbackSoleProfile.Point{footPosition=V(p.GetProperty("footPosition")),toePosition=V(p.GetProperty("toePosition")),toeWeight=p.GetProperty("toeWeight").GetSingle()};weights[index][ids[i].GetInt32()]=data[i].toeWeight;}if(index==0)asset.left=data;else asset.right=data;}}}
    }
    private sealed class Rig
    {
        public GameObject root;public Transform[] bones;public Animator animator;public IntercomGroundFeedback feedback;public IntercomPlayerMotor motor;public CharacterController controller;public int contacts;public bool invalidEvent;public float maximumContactLocalPhase;public Fixture fixture;public ProfileData profile;
        public Rig(Fixture source,ProfileData skin,bool correction,float offset){fixture=source;profile=skin;root=new GameObject("Running fixture");controller=root.AddComponent<CharacterController>();controller.height=1.5f;controller.center=new Vector3(0,.75f+source.idle.meshMinimum.Min(),0);motor=root.AddComponent<IntercomPlayerMotor>();motor.modelForwardYaw=0;Check(Math.Abs(motor.strafeSpeedRatio-.75f)<1e-6f,"fixture matches authored lateral stride ratio");animator=root.AddComponent<Animator>();bones=source.names.Select(n=>new GameObject(n).transform).ToArray();for(int i=0;i<bones.Length;i++){bones[i].parent=source.parents[i]<0?root.transform:bones[source.parents[i]];root.children.Add(bones[i]);}Apply(source.idle);var idle=new AnimationClip{name="Idle",sample=_=>Apply(source.idle)};animator.runtimeAnimatorController=new RuntimeAnimatorController{animationClips=new[]{idle}};animator.SetFloat(Animator.StringToHash("Speed"),1);feedback=root.AddComponent<IntercomGroundFeedback>();feedback.motor=motor;feedback.animator=animator;feedback.body=bones[0];feedback.torso=bones[1];feedback.leftCalf=bones[2];feedback.rightCalf=bones[3];feedback.leftFoot=bones[4];feedback.rightFoot=bones[5];feedback.leftToe=bones[6];feedback.rightToe=bones[7];feedback.plantFeet=correction;feedback.soleProfile=skin.asset;
            var l=source.calibration.GetProperty("L");var r=source.calibration.GetProperty("R");feedback.leftSoleOffset=V(l.GetProperty("centreLocal"))*source.scale;feedback.rightSoleOffset=V(r.GetProperty("centreLocal"))*source.scale;feedback.leftHeelOffset=V(l.GetProperty("heelLocal"))*source.scale;feedback.rightHeelOffset=V(r.GetProperty("heelLocal"))*source.scale;feedback.leftToeOffset=V(l.GetProperty("toeLocal"))*source.scale;feedback.rightToeOffset=V(r.GetProperty("toeLocal"))*source.scale;feedback.soleOffsetsCalibrated=feedback.contactMarkersCalibrated=true;Set(feedback,"soleCalibrationVersion",1);Set(feedback,"calibratedSoleProfile",skin.asset);Call(motor,"Awake");Call(feedback,"Awake");Call(feedback,"CalibrateSoleClouds");Call(feedback,"OnEnable");root.transform.position=new Vector3(0,offset,0);Physics.Floor=new GameObject("floor").AddComponent<Collider>();Physics.FloorHeight=0;Physics.FloorNormal=Vector3.up;feedback.Footstep+=(c,p,s,left)=>{contacts++;float local=animator.state.normalizedTime-(left?0f:.5f);local-=(float)Math.Floor(local);maximumContactLocalPhase=Math.Max(maximumContactLocalPhase,local);if(!motor.IsGrounded||motor.ActualPlanarSpeed<.08f||feedback.IsTurnFootstep)invalidEvent=true;};Check(feedback.ProvidesFootContacts,"calibrated contact provider");}
        public void Apply(Frame f){for(int i=0;i<bones.Length;i++){bones[i].localPosition=f.bones[i].position;bones[i].localRotation=f.bones[i].rotation;bones[i].localScale=f.bones[i].scale;}}
        public void Tick(Frame f,Vector3 rootPosition,Vector3 velocity,float phase,float dt,bool grounded=true){Time.deltaTime=dt;Time.frameCount++;Call(feedback,"Update");root.transform.position=rootPosition;Apply(f);controller.isGrounded=grounded;Property(motor,"ActualPlanarVelocity",velocity);Property(motor,"ActualPlanarSpeed",velocity.magnitude);Property(motor,"WantsToMove",velocity.sqrMagnitude>0);animator.state=new AnimatorStateInfo{fullPathHash=113,normalizedTime=phase};var parameters=new Vector3(velocity.x/.75f,0,velocity.z).normalized;animator.SetFloat(Animator.StringToHash("MoveX"),parameters.x);animator.SetFloat(Animator.StringToHash("MoveY"),parameters.z);float reference=(new Vector3(parameters.x*.75f,0,parameters.z)).magnitude;animator.SetFloat(Animator.StringToHash("RunRate"),reference>0.001f?velocity.magnitude/reference:1f);var lengths=new[]{Vector3.Distance(bones[4].position,bones[2].position),Vector3.Distance(bones[5].position,bones[3].position)};Call(feedback,"LateUpdate");for(int side=0;side<2;side++)Check(Math.Abs(Vector3.Distance(bones[4+side].position,bones[2+side].position)-lengths[side])<1e-5f,"rigid calf length changed");for(int i=2;i<bones.Length;i++){Check(Vector3.Distance(bones[i].localPosition,f.bones[i].position)<1e-6f,"runtime changed leg local translation");Check(Vector3.Distance(bones[i].localScale,f.bones[i].scale)<1e-6f,"runtime changed leg scale");}Check(!invalidEvent,"airborne/idle or turn-authorized running event");}
    }
    private sealed class CaseResult
    {
        public string clip;public float pace,speed,rootOffset;public bool corrected;public int flatSamples,stanceSamples,contacts;public float flatMinimum=float.MaxValue,flatMaximum=float.MinValue,stanceMinimum=float.MaxValue,stanceMaximum=float.MinValue,maxBodyCorrection,maxSourceCloudInterpolationError,maxSlipSpeed,maximumCalfCorrectionDegrees,maximumContactLocalPhase,cycleMinimum=float.MaxValue,maximumFootSpeed,maximumBodySpeed,cycleMinimumPhase,maximumFootSpeedPhase;public int cycleMinimumSide,maximumFootSpeedSide;public double meanSlipSpeed;public int slipSamples;
    }
    private static Vector3 Travel(string clip){if(clip.Contains("+")){var pair=clip.Split('+');return (Travel(pair[0])+Travel(pair[1])).normalized;}return clip.Contains("Backward")?new Vector3(0,0,-1):clip.Contains("Left")?new Vector3(1,0,0):clip.Contains("Right")?new Vector3(-1,0,0):Vector3.forward;}
    private static float Reference(string clip){var travel=Travel(clip);var parameters=new Vector3(travel.x/.75f,0,travel.z).normalized;return new Vector3(parameters.x*.75f,0,parameters.z).magnitude;}
    private static CaseResult Run(Fixture source,ProfileData profile,string clip,float pace,float offset,bool corrected,List<object> trace=null)
    {
        float speed=pace*Reference(clip);var rig=new Rig(source,profile,corrected,offset);var result=new CaseResult{clip=clip,pace=pace,speed=speed,rootOffset=offset,corrected=corrected};float frequency=pace*24f/16f;const float dt=1f/60f;int frames=(int)Math.Ceiling(4/frequency/dt);Vector3 travel=Travel(clip);var tracking=new bool[2];var cycle=new int[2];var material=new Vector3[2];var previous=new Vector3[2];var previousFeet=new Vector3[2];Vector3 previousBody=Vector3.zero;
        for(int i=0;i<=frames;i++){float time=i*dt,phase=time*frequency;var pose=source.At(clip,phase);Vector3 rootPosition=travel*(time*speed)+new Vector3(0,offset,0);rig.Tick(pose,rootPosition,travel*speed,phase,dt);float body=Vector3.Distance(rig.bones[0].localPosition,pose.bones[0].position);result.maxBodyCorrection=Math.Max(result.maxBodyCorrection,body);if(phase>=1&&i>0){result.maximumBodySpeed=Math.Max(result.maximumBodySpeed,Vector3.Distance(rig.bones[0].position,previousBody)/dt);for(int side=0;side<2;side++){float velocity=Vector3.Distance(rig.bones[4+side].position,previousFeet[side])/dt;if(velocity>result.maximumFootSpeed){result.maximumFootSpeed=velocity;result.maximumFootSpeedPhase=phase-(float)Math.Floor(phase);result.maximumFootSpeedSide=side;}}}previousBody=rig.bones[0].position;for(int side=0;side<2;side++)previousFeet[side]=rig.bones[4+side].position;for(int side=0;side<2;side++){float dot=Math.Abs(N.Quaternion.Dot(pose.bones[2+side].rotation.n,rig.bones[2+side].localRotation.n));float angle=2f*(float)Math.Acos(Math.Clamp(dot,-1f,1f))*180f/(float)Math.PI;result.maximumCalfCorrectionDegrees=Math.Max(result.maximumCalfCorrectionDegrees,angle);}if(trace!=null&&time<=1.5f)trace.Add(new{time,phase,root=A(rootPosition),bones=rig.bones.Select(b=>new{position=A(b.position),rotation=A(b.rotation),scale=A(b.lossyScale)}).ToArray()});
            for(int side=0;side<2;side++){var foot=rig.bones[4+side];var footMatrix=foot.localToWorldMatrix.value;var toeMatrix=rig.bones[6+side].localToWorldMatrix.value;float minimum=profile.truth[side].Min(p=>(N.Vector3.Transform(p.footLocal.n,footMatrix)*(1f-p.weight)+N.Vector3.Transform(p.toeLocal.n,toeMatrix)*p.weight).Y);float local=(phase-(side==1?.5f:0));int currentCycle=(int)Math.Floor(local);local-=(float)Math.Floor(local);float weight=IntercomGroundMath.StanceWeight(phase,side==0);float friction=IntercomGroundMath.PlantLockWeight(phase,side==0);bool flat=friction>.999f;if(phase>=1&&minimum<result.cycleMinimum){result.cycleMinimum=minimum;result.cycleMinimumPhase=phase-(float)Math.Floor(phase);result.cycleMinimumSide=side;}
                if(phase>=1&&weight>.001f){result.stanceSamples++;result.stanceMinimum=Math.Min(result.stanceMinimum,minimum);result.stanceMaximum=Math.Max(result.stanceMaximum,minimum);}if(phase>=1&&flat){result.flatSamples++;result.flatMinimum=Math.Min(result.flatMinimum,minimum);result.flatMaximum=Math.Max(result.flatMaximum,minimum);}
                if(!corrected&&!clip.Contains("+")){float actual=pose.meshMinimum[side]+offset;result.maxSourceCloudInterpolationError=Math.Max(result.maxSourceCloudInterpolationError,Math.Abs(minimum-actual));}
                if(flat){if(!tracking[side]||cycle[side]!=currentCycle){var candidates=pose.cloud[side].Where(kv=>profile.weights[side].TryGetValue(kv.Key,out float w)&&w<.001f).ToArray();var selected=(candidates.Length>0?candidates:pose.cloud[side].ToArray()).OrderBy(kv=>foot.TransformPoint(kv.Value).y).First();material[side]=selected.Value;tracking[side]=true;cycle[side]=currentCycle;}else if(phase>=1){float slip=Vector3.ProjectOnPlane(foot.TransformPoint(material[side])-previous[side],Vector3.up).magnitude/dt;result.maxSlipSpeed=Math.Max(result.maxSlipSpeed,slip);result.meanSlipSpeed+=slip;result.slipSamples++;}previous[side]=foot.TransformPoint(material[side]);}else tracking[side]=false;
            }
        }
        result.contacts=rig.contacts;result.maximumContactLocalPhase=rig.maximumContactLocalPhase;if(result.slipSamples>0)result.meanSlipSpeed/=result.slipSamples;Check(result.flatSamples>0&&result.slipSamples>0,"fixture must sample complete flat supports");
        if(corrected){Check(result.flatMinimum>.001f&&result.flatMaximum<.006f,"flat sole must remain near the ground: "+clip);Check(result.meanSlipSpeed<.005,"flat contact cannot skate: "+clip);Check(result.cycleMinimum>=-.0005f,"weighted true-bind sole cannot penetrate during swing: "+clip);Check(result.maximumFootSpeed<=6f,"swing or support entry cannot snap the ankle: "+clip);Check(result.maximumBodySpeed<=4f,"support solve cannot snap the Body: "+clip);Check(result.maximumCalfCorrectionDegrees<=45f,"running correction exceeds the rigid leg envelope: "+clip);Check(result.maxSlipSpeed<.02f,"single-frame flat contact cannot skate: "+clip);Check(result.maxBodyCorrection<.065f,"Body support correction exceeds safe envelope");Check(result.maximumContactLocalPhase<.12f+frequency*dt,"running sound must coincide with early support");Check(result.contacts>=7&&result.contacts<=9,"one event per support cycle");}
        // Extend exported demonstrations to a true 1.5 seconds without changing
        // the four-cycle numerical window or its contact-count assertion.
        if(trace!=null)for(int i=frames+1;i<=(int)Math.Round(1.5f/dt);i++){float time=i*dt,phase=time*frequency;var pose=source.At(clip,phase);Vector3 rootPosition=travel*(time*speed)+new Vector3(0,offset,0);rig.Tick(pose,rootPosition,travel*speed,phase,dt);trace.Add(new{time,phase,root=A(rootPosition),bones=rig.bones.Select(b=>new{position=A(b.position),rotation=A(b.rotation),scale=A(b.lossyScale)}).ToArray()});}
        int atReset=rig.contacts;Property(rig.motor,"MotionResetVersion",rig.motor.MotionResetVersion+1u);rig.Tick(source.At(clip,4.18f),new Vector3(3,offset,2),travel*speed,4.18f,dt);Check(rig.contacts==atReset,"teleport reset cannot invent a plant");
        int before=rig.contacts;for(int i=0;i<10;i++)rig.Tick(source.At(clip,4.1f+i*.03f),new Vector3(0,offset,0),travel*speed,4.1f+i*.03f,dt,false);Check(rig.contacts==before,"airborne running cannot publish a plant");
        Call(rig.motor,"OnApplicationFocus",false);Call(rig.feedback,"OnApplicationFocus",false);for(int i=0;i<3;i++)rig.Tick(source.At(clip,6f+i*.05f),new Vector3(2,offset,2),travel*speed,6f+i*.05f,dt,true);Check(rig.contacts==before,"focus loss cannot publish a stale running plant");Call(rig.motor,"OnApplicationFocus",true);Call(rig.feedback,"OnApplicationFocus",true);rig.Tick(source.At(clip,6.18f),new Vector3(2,offset,2),travel*speed,6.18f,dt,true);Check(rig.contacts==before,"focus resume mid-support cannot invent a landing");
        Call(rig.motor,"OnApplicationPause",true);Call(rig.feedback,"OnApplicationPause",true);rig.Tick(source.At(clip,7f),new Vector3(2,offset,2),travel*speed,7f,dt,true);Check(rig.contacts==before,"paused running cannot publish a landing");Call(rig.motor,"OnApplicationPause",false);Call(rig.feedback,"OnApplicationPause",false);rig.Tick(source.At(clip,7.18f),new Vector3(2,offset,2),travel*speed,7.18f,dt,true);Check(rig.contacts==before,"pause resume mid-support cannot invent a landing");
        for(int i=0;i<10;i++)rig.Tick(source.idle,new Vector3(0,offset,0),Vector3.zero,0,dt,true);Check(rig.contacts==before,"ordinary idle cannot publish a running plant");Call(rig.feedback,"OnDisable");Check(Field<int>(rig.feedback,"savedPoseCount")==0,"disable restores pose cache");return result;
    }
    private static void VerifyClearanceReset(Fixture source,ProfileData profile)
    {
        var rig=new Rig(source,profile,true,0f);const float dt=1f/60f;
        Action force=()=>{foreach(string side in new[]{"leftRig","rightRig"}){object foot=Field<object>(rig.feedback,side);Set(foot,"clearanceActive",true);Set(foot,"clearanceDirection",new Vector3(.6f,0,.8f));}};
        Action<string> cleared=reason=>{foreach(string side in new[]{"leftRig","rightRig"}){object foot=Field<object>(rig.feedback,side);Check(!Field<bool>(foot,"clearanceActive"),reason+" leaves no active running clearance");Check(Field<Vector3>(foot,"clearanceDirection").sqrMagnitude<1e-10f,reason+" leaves no stale running direction");}};
        rig.Tick(source.idle,Vector3.zero,Vector3.zero,0f,dt);
        force();Property(rig.motor,"MotionResetVersion",rig.motor.MotionResetVersion+1u);rig.Tick(source.idle,Vector3.zero,Vector3.zero,.01f,dt);cleared("motion reset while already idle");
        rig.Tick(source.At("Run",.18f),Vector3.zero,Vector3.forward*1.8f,.18f,dt);Check(Field<bool>(rig.feedback,"sampleRunningSoles"),"clearance exit test starts in running solver");force();rig.Tick(source.idle,Vector3.zero,Vector3.zero,.19f,dt);cleared("running to idle without phase discontinuity");
        rig.root.transform.rotation=Quaternion.AngleAxis(20f,Vector3.up);rig.Tick(source.idle,Vector3.zero,Vector3.zero,.20f,dt);cleared("standing turn after running");
        force();Call(rig.feedback,"OnApplicationFocus",false);cleared("focus loss");Call(rig.feedback,"OnApplicationFocus",true);
        force();Call(rig.feedback,"OnApplicationPause",true);cleared("pause");Call(rig.feedback,"OnApplicationPause",false);
        force();Call(rig.feedback,"OnDisable");cleared("disable");
    }
    private static void VerifyTransformStandIn()
    {
        var parent=new GameObject("affine parent").transform;parent.localPosition=new Vector3(2,-1,3);parent.localRotation=Quaternion.Euler(17,32,-9);parent.localScale=new Vector3(1.3f,.7f,1.1f);var child=new GameObject("affine child").transform;child.parent=parent;child.localPosition=new Vector3(.2f,.5f,-.3f);child.localRotation=Quaternion.Euler(-21,8,13);child.localScale=new Vector3(.8f,1.4f,.9f);var matrix=child.localToWorldMatrix;var random=new Random(721);for(int i=0;i<100;i++){var point=new Vector3((float)random.NextDouble(),(float)random.NextDouble(),(float)random.NextDouble());var world=child.TransformPoint(point);Check(Vector3.Distance(world,matrix.MultiplyPoint3x4(point))<2e-6f,"cached affine matrix agrees with recursive TRS");Check(Vector3.Distance(point,child.InverseTransformPoint(world))<2e-6f,"recursive inverse retains nonuniform parent scale");}var saved=matrix.MultiplyPoint3x4(Vector3.one);parent.localPosition+=Vector3.up;Check(Vector3.Distance(saved,matrix.MultiplyPoint3x4(Vector3.one))==0,"cached matrix is a value snapshot");
    }
    private static void WriteTrace(string path,string suffix,Fixture source,string clip,List<object> frames,JsonSerializerOptions options)
    {
        string target=Path.Combine(Path.GetDirectoryName(path)??"",Path.GetFileNameWithoutExtension(path)+suffix+".json");
        File.WriteAllText(target,JsonSerializer.Serialize(new{coordinates="Unity test convention (source x,z,-y)*scale; quaternion XYZW",source.scale,source.sourceHash,bones=source.names,clip,speed=2.1f*Reference(clip),pace=2.1f,fps=60,frames},options));
    }
    private static void Main(string[] args)
    {
